insert into public.projects (title, description, tech, category, github, demo, featured, has_interactive_demo, sort_order) values
  ('Git Release Analyzer', 'AI tool that compares release branches using Git APIs, producing rich summaries of code changes, commits, MRs, developers, and reviewers. Generates separate non-technical Business Summaries and detailed Technical summaries for deployment risk auditing.', array['Python', 'Git API', 'OpenAI', 'FastAPI', 'React']::text[], 'AI', 'https://github.com/khazaShaik', null, true, true, 0),
  ('Agent Studio — Onboard Any Service, Generate Its Tests', 'A generic tool that takes a service from "here is my repo" to a running test suite. It ingests seven source types — Git code, Swagger/OpenAPI, Confluence runbooks, database schema, qTest and Splunk — into a searchable per-service domain, builds a cross-source dependency graph, then generates positive, negative and edge scenarios filled with data that satisfies real schema constraints and executes them with per-step validation and reporting. Nothing is service-specific: onboarding a new API is configuration, not code. The LLM handles extraction and scenario design while deterministic code runs and validates every step, so failures stay reproducible.', array['React 19', 'TypeScript', 'Python', 'FastAPI', 'LangGraph', 'RAG', 'pgvector', 'SSE']::text[], 'AI', 'https://github.com/khazaShaik', null, true, true, 1),
  ('DocuMind — RAG-Powered Doc Assistant', 'Retrieval-augmented Q&A system over technical documentation. Ingests PDFs and Markdown, chunks with recursive splitting, embeds via OpenAI, and retrieves via ChromaDB with hybrid search and cross-encoder reranking. Returns answers with cited sources and holds up well against a hand-built evaluation set.', array['Python', 'LangChain', 'OpenAI', 'ChromaDB', 'FastAPI', 'RAG']::text[], 'AI', 'https://github.com/khazaShaik', null, true, false, 2),
  ('AgentFlow — Multi-Agent Workflow', 'Multi-agent orchestration system built with LangGraph. Four agents (planner, retriever, executor, critic) collaborate through shared state with tool calling, function routing, and self-correction loops. It triages GitHub issues and drafts contextual responses, taking a lot of the manual work out of issue triage.', array['Python', 'LangGraph', 'LangChain', 'OpenAI', 'Function Calling', 'AI Agents']::text[], 'AI', 'https://github.com/khazaShaik', null, true, false, 3),
  ('T-Mobile SCM Platform', 'Cloud-native supply chain platform used across thousands of T-Mobile retail stores. Owns the DRI / DRO / DLM modules that handle a high daily volume of inventory transactions, with Kafka async flows, Cassandra-tuned hot paths, and Kubernetes orchestration. Currently delivering the TIMO Console and TIMO iOS app.', array['Spring Boot', 'Java 17', 'Apigee', 'Cassandra', 'Kafka', 'Kubernetes', 'Angular 16']::text[], 'Enterprise', null, null, false, false, 4),
  ('CREW Rest Day Logic — Union Pacific Railroad', 'Designed and delivered Rest Day functionality for Union Pacific Railroad''s crew allocation system, serving a ~4,000-member crew workforce with calculations running daily. Built it as a configurable rule engine that enforces the mandated rest gap between shifts (12–24 hours by role and policy), integrated end to end into the CREW module.', array['Spring Boot', 'Java 11', 'Reactive Programming', 'Angular 11', 'Splunk']::text[], 'Enterprise', null, null, false, false, 5),
  ('ERCS — Electronic Receipt System', 'Electronic receipt and confirmation system for CCIL, handling collateral notices across its member network — India''s major banks and financial institutions clearing through CCIL and NSE in the money, G-Sec, and derivative markets. Live in production at enotice.ccilindia.com.', array['Spring', 'REST', 'Oracle', 'AngularJS', 'JPA', 'Tomcat']::text[], 'Enterprise', null, 'https://enotice.ccilindia.com', false, false, 6),
  ('eTokens — Coupons Management', 'SEO-friendly coupons management platform enabling merchants to create, distribute, and track coupon campaigns with real-time analytics and redemption tracking.', array['Angular', 'Spring Boot', 'Java', 'REST API']::text[], 'Enterprise', 'https://github.com/khazaShaik', null, false, false, 7),
  ('Vendor Management System (VMS)', 'Platform for businesses to manage their contingent vendor ecosystem — obtaining quotes with pricing, capabilities, and turnaround times in one place.', array['Java', 'Spring', 'AngularJS', 'REST', 'Oracle']::text[], 'Enterprise', 'https://github.com/khazaShaik/VMS', null, false, false, 8);
insert into public.experience (role, company, duration, location, client, highlights, tech_ai, tech, sort_order) values
  ('Senior Software Engineer (Lead)', 'Concentrix', 'Jun 2025 – Present', 'Hyderabad, India', 'T-Mobile — Supply Chain Management (SCM)', array['Lead TOP-Elevate, a test orchestration platform that lets any tester run full end-to-end supply-chain journeys from one screen, without needing SAP, API, or database knowledge', 'Designed the architecture: an LLM generates schema-valid test data and picks reusable step templates, while deterministic code runs the SAP, API, and database steps (Cassandra, MongoDB) and validates each result — keeping the LLM boundary narrow so failures stay debuggable', 'Hands-on across the stack — built the critical paths myself: the test-data generation engine, step-execution runtime, and per-run validation reporting, in Python (FastAPI, LangChain) with a React front-end', 'Lead a team of 4 (2 devs, 1 QA, 1 dev-test) and mentor 4–5 junior developers — own the key design decisions, run design and code reviews each sprint, and shape the roadmap with product owners', 'Cut end-to-end test setup from a multi-team, multi-day effort to minutes — OEM data loads from a 24–48 hour ticket to 5 minutes — saving a measured 8,000+ engineering hours across 4,400+ test cases, 8 environments and 8 distribution centres, with monthly usage up ~40x as teams adopted it', 'Widened what gets tested — teams previously covered only the happy path; integration, negative, and security scenarios are now routine, catching failures that used to reach production']::text[], array['Python', 'FastAPI', 'LangChain', 'RAG', 'AI Agents', 'React']::text[], array['Java', 'Spring Boot', 'Angular 17', 'REST APIs', 'Kafka', 'Cassandra', 'MongoDB']::text[], 0),
  ('Cloud Consultant', 'Concentrix', 'Feb 2023 – Jun 2025', 'Hyderabad, India', 'T-Mobile — Supply Chain Management (SCM)', array['Owned three SCM modules (DRI / DRO / DLM) serving ~3,000 T-Mobile retail stores, on a device-lifecycle platform carrying 18M+ daily transactions across 50+ boundary systems — took them from weekly P1 pages to almost none by fixing root causes rather than patching symptoms', 'Delivered features across TIMO Console (Angular back-office) and the TIMO 2.0 iOS app on a ~55-microservice retail inventory platform, replacing manual reconciliation with system-tracked movement and SOX-compliant inventory reporting', 'Built Spring Boot microservices with REST APIs and Angular/TypeScript front-ends, and worked across the Kafka event pipeline that keeps store-level Stock on Hand in sync for BOPIS, buy-online-while-in-store, and same-day delivery', 'Tuned Cassandra queries and reshaped the data models behind the hot paths, and replaced synchronous batch processing with Kafka-based asynchronous flows to remove the throughput ceiling on large data loads', 'Set up CI/CD with GitLab pipelines and Azure DevOps using Docker and Kubernetes, moving releases from manual steps to a continuous dev → UAT → pre-prod → production flow that ships every sprint on a per-feature basis']::text[], array[]::text[], array['Java 17', 'Spring Boot', 'Microservices', 'Angular', 'TypeScript', 'REST APIs', 'Cassandra', 'Kafka', 'AWS', 'Kubernetes']::text[], 1),
  ('Software Engineer 1', 'ProKarma', 'Jul 2019 – Jan 2023', 'Hyderabad, India', 'T-Mobile US, Inc. & Union Pacific Railroad', array['Delivered back-end and Angular UI features on DASH, T-Mobile''s postpaid order platform for retail and care reps — activations, add-a-line, and device sales across six finance types (FRP, EIP, JOD, CCR, BOPIS, BOWIS)', 'Owned production defect resolution on DASH — including Redis cache-consistency bugs where stale catalog loads surfaced as wrong pricing at the point of sale, traced across ~15 interfacing systems (SAP, MPM, DPS, Samson, xECM)', 'Set up blue-green deployments so releases shipped without a maintenance window, and migrated service credentials to HashiCorp Vault — removing hard-coded secrets and making rotation a config change, not a redeploy', 'Delivered Crew Allocation and Time Management for Union Pacific Railroad — a Rest Day engine running daily for a ~4,000-member crew workforce, with configurable rules enforcing the mandated 12–24 hour rest gap between shifts by role and policy']::text[], array[]::text[], array['Java', 'Spring Boot', 'Oracle', 'Redis', 'REST APIs', 'Angular', 'Vault', 'Splunk', 'GitLab CI/CD']::text[], 2),
  ('Software Engineer', 'Tata Consultancy Services', 'Feb 2016 – Jul 2019', 'Mumbai, India', 'CCIL — Clearing Corporation of India Ltd.', array['Delivered ERCS for collateral notices at CCIL, India''s central counterparty for clearing and settlement — live in production at enotice.ccilindia.com and used across its member network of major Indian banks and financial institutions', 'Built CRM (Credit Risk Monitoring) from scratch to ingest member-bank data, calculate risk scores, and auto-categorize participants, replacing a slow multi-day manual process with a quick automated workflow', 'Modernised a legacy monolith from Java 6 to Java 8, moving business logic behind REST services — improved performance and left the codebase far easier to maintain', 'Owned four applications full stack — APIs, UI, SQL schema design, and testing — with a strong track record for production stability']::text[], array[]::text[], array['Java 6 → 8', 'Spring', 'REST', 'Oracle', 'SQL', 'Tomcat', 'AngularJS', 'JSP', 'JPA', 'Git']::text[], 3);
