  ('Data & Messaging', '[{"name":"SQL","icon":"HiTableCells","color":"#0EA5E9"},{"name":"Oracle / PL-SQL","icon":"HiCircleStack","color":"#F80000"},{"name":"PostgreSQL","icon":"SiPostgresql","color":"#4169E1"},{"name":"MongoDB","icon":"SiMongodb","color":"#47A248"},{"name":"Cassandra","icon":"SiApachecassandra","color":"#1287B1"},{"name":"Redis / Caching","icon":"SiRedis","color":"#DC382D"},{"name":"Kafka","icon":"SiApachekafka","color":"#231F20"},{"name":"RabbitMQ","icon":"SiRabbitmq","color":"#FF6600"},{"name":"Splunk","icon":"SiSplunk","color":"#65A637"},{"name":"Observability & Monitoring","icon":"HiPresentationChartLine","color":"#F59E0B"},{"name":"Data Modeling","icon":"HiRectangleGroup","color":"#8B5CF6"}]'::jsonb, 4),
